  const eol=text.includes('\r\n')?'\r\n':'\n',note=entry.text.replace(/\n/g,eol);
  if(entry.position==='prepend'){const bom=text.charCodeAt(0)===0xFEFF?'\uFEFF':'';return Buffer.from(bom+note+eol+text.slice(bom.length));}
