 for(const before of entry.before)for(const eol of ['\n','\r\n']){const candidate=before.replace(/\n/g,eol),start=text.indexOf(candidate);if(start>=0){if(text.indexOf(candidate,start+candidate.length)>=0)throw Error('Ambiguous source: '+entry.file);if(!matches.some(m=>m.start===start&&m.before===candidate))matches.push({start,before:candidate,after:after.replace(/\n/g,eol)})}}
 if(matches.length!==1)throw Error('Expected source block not found uniquely: '+entry.file);
